INSERT INTO supplier_options(name,region,website,product_categories,published_terms,costs_confirmed,status) VALUES
('MP DROP','Brasil','https://mpdrop.app/','Casa e organização: confirmar no catálogo autenticado; priorizar kits leves e não frágeis.','Acesso sem mensalidade informado para cadastros até 31/12/2026; pagamento do custo por pedido via Pix; plataforma informa NF-e e rastreio. Confirmar SKU, frete, estoque e política de devolução antes de selecionar.',false,'needs_verification'),
('Dropnacional via Dropi','Brasil','https://dropnacional.com.br/','Catálogo nacional amplo; filtrar por casa e organização após login.','Teste informado de 3 dias; plano profissional anunciado a partir de R$ 89/mês depois do teste. Produto e frete pagos por pedido; notas fiscais e envio direto anunciados.',false,'needs_verification'),
('CJdropshipping','Internacional','https://cjdropshipping.com/','Organização compacta, acessórios de cozinha e armazenamento; preferir armazém próximo ao Brasil se disponível.','Plano básico anunciado a US$ 0/mês; cada pedido cobra produto e logística. Cotar frete, prazo e impostos para o CEP do cliente; estoque e qualidade variam por SKU.',false,'needs_verification'),
('AliExpress — fornecedor individual','Internacional','https://www.aliexpress.com/','Organizadores leves; apenas vendedores que confirmem por escrito dropshipping sem material promocional e rastreamento.','Não tratar marketplace como garantia de dropshipping: vendedor, custo, prazo, importação e devoluções devem ser verificados individualmente. Não conectar automaticamente sem credenciais e testes.',false,'needs_verification')
